# ==============================================================
# Architect Engine — Enhanced CAD Editor & Ready 2D Blocks Library
# (Matching user reference UI: Dark/Light CAD, Action Bar, Edit Modal, & 2D Blocks)
# Run with: python3 fix_and_update.py
# ==============================================================
import os
import base64

FILES = {
    "lib/models/cad_models.dart": "",
    "lib/screens/cad_editor_screen.dart": "",
    "lib/screens/project_form_dialog.dart": "",
    "lib/screens/professional_screen.dart": "",
    "lib/widgets/app_drawer.dart": "",
    "lib/screens/home_screen.dart": "",
}

def main():
    print("🚀 Applying Enhanced CAD Editor & Ready-Made Blocks to Architect Engine...")
    for rel_path, b64_content in FILES.items():
        dir_name = os.path.dirname(rel_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        raw_bytes = base64.b64decode(b64_content.encode("ascii"))
        with open(rel_path, "wb") as f:
            f.write(raw_bytes)
        print(f"  ✓ Updated: {rel_path}")

    print("")
    print("✅ All 6 enhanced files applied successfully!")
    print("Commit and push to GitHub to trigger clean build:")
    print('  git add .')
    print('  git commit -m "feat(cad): add ready 2D architectural blocks library, selection action bar, and edit modal"')
    print('  git push')

if __name__ == "__main__":
    main()